parameters.jsCode:
// Sanitize fixture → commit payload. No live Gmail.
const i = items[0].json;
const sourceId = i.source_id || i.id || ('fixture-' + Date.now());
const leadId = i.lead_id || ('lead-' + sourceId);
return [{
  json: {
    source_id: sourceId,
    lead_id: leadId,
    subject: i.subject || '',
    from_email: i.from_email || '',
    raw_text: i.raw_text || i.snippet || '',
    client_name: i.client_name || null,
    phone: i.phone || null,
    email: i.email || null,
    site: i.site || null,
    service: i.service || null,
    summary: i.summary || null,
    manager_status: i.manager_status || 'new',
    correlation_id: i.correlation_id || ('corr-' + sourceId),
    workflow_version: 'Operational.v3.rollback',
    dry_run_telegram: true,
    gmail_finalize_simulated: false
  }
}];

const r = items[0].json.commit_result || items[0].json;
const allow = !!(r.gmail_finalize_allowed);
return [{ json: {
  commit: r,
  gmail_finalize_allowed: allow,
  gmail_finalize_status: allow ? 'SIMULATED_OK_INACTIVE' : 'BLOCKED',
  note: 'Candidate inactive: Gmail labels not applied to production mailbox'
} }];

// HARD: dry-run only — zero Telegram API calls
const claimed = items[0].json.claimed || items[0].json;
const rows = (claimed.claimed || []);
const out = [];
for (const d of rows) {
  out.push({
    json: {
      delivery_id: d.delivery_id,
      dry_run: true,
      telegram_sent: false,
      mark_status: 'sent',
      external_message_id: 'dryrun-' + d.delivery_id
    }
  });
}
if (!out.length) return [{ json: { dry_run: true, claimed_count: 0 } }];
return out;

